// Pirate Borg — Core Rules creatures (pg. 86-113), Marrow Cannons, Archetype Captains and the
// "The Curse of Skeleton Point" module NPCs (pg. 132-161). Page = printed page = PDF page.
// Every block transcribed from the rasterised Core Rules page images and cross-checked against the
// Creature Index (pg. 164). Prose is paraphrased; numbers and names are exact.
//
// Same shape as bestiary.mjs (PbMonster). Extra optional fields used here:
//   hpText      — display string when HP isn't a plain number ("2d8", "d10", "4 each", "N/A"); `hp` then holds a
//                 representative number (average, rounded down) so trackers keep working.
//   moraleText  — likewise for a rolled Morale ("d6+6").
//   attackChoice: "pick 1-2" — the block says "Choose 1 or 2" weapons (customisable minion).
//   naval       — sea monsters' second stat block for Naval Combat (pg. 73): { hp, morale, armor, speed, agility, attacks, specials }.
//   loot        — sellable parts ("Snake skin 5s").  count — group size die.  captain — archetype captain id.

const CR = "Core Rules";
const SP = "The Curse of Skeleton Point";
const A = (name, damage, notes) => ({ name, damage, ...(notes ? { notes } : {}) });
const S = (name, text) => ({ name, text });
const AR = (name, die) => ({ name, die, tier: { d2: 1, d4: 2, d6: 3 }[die] });
const L = (name, value, note) => ({ name, value, ...(note ? { note } : {}) });

const SKELETON_RULE = S("Skeleton", "Any skeleton that takes more than 5 damage (after armor) at once tumbles into a pile of bones. Without a Cap'n or Warlock nearby, skeletons that fail a morale test crumble into ASH.");
const ZOMBIE_INFECTION = S("Zombie Infection", "Zombies don't breathe air. Anyone bitten by a zombie tests TOUGHNESS DR8 or dies within two days, then rises as a zombie. A zombie that eats flesh recovers d4 HP (d8 if it's a brain).");
const GHOST_TERROR = S("Ghostly Terror", "Anyone seeing ghosts for the first time tests SPIRIT DR12 or flees in terror; they may test again at the start of each turn. Ghosts love grog and rum (especially with black powder in it), and some plant roots are dangerous to them.");
const SEA_MONSTER = S("Sea Monster", "In Naval Combat sea monsters aren't affected by wind and can move up to their speed in any direction.");

